    container_name: frame-inventory-mariadb-primary
    ports:
      - "3306:3306"
    environment:
      MARIADB_ROOT_PASSWORD: root
      MARIADB_DATABASE: frames
      MARIADB_USER: app
      MARIADB_PASSWORD: app
    volumes:
      - mariadb-primary-data:/var/lib/mysql
    networks:
      - frame-inventory

  opensearch:
    image: opensearchproject/opensearch:2.18.0
    container_name: frame-inventory-opensearch
    environment:
      cluster.name: frame-inventory-cluster
      node.name: opensearch
      discovery.type: single-node
      bootstrap.memory_lock: "true"
      OPENSEARCH_JAVA_OPTS: "-Xms512m -Xmx512m"
      DISABLE_SECURITY_PLUGIN: "true"
      DISABLE_INSTALL_DEMO_CONFIG: "true"
    ulimits:
      memlock:
        soft: -1
        hard: -1
      nofile:
        soft: 65536
        hard: 65536
