      - opensearch-data:/usr/share/opensearch/data
    networks:
      - frame-inventory

  opensearch-dashboards:
    image: opensearchproject/opensearch-dashboards:2.18.0
    container_name: frame-inventory-opensearch-dashboards
    ports:
      - "5601:5601"
    environment:
