              </div>
              <div className="field">
                <label>Dimensions (W Ã— H mm)</label>
                <input type="text" defaultValue={frame.format.dimensions} />
              </div>
              <div className="field">
                <label>Resolution (px)</label>
                <input type="text" defaultValue={frame.format.resolution} />
              </div>
              <div className="field">
