              </div>
              <div className="field" style={{marginBottom: 16}}>
                <label>Position within site <span className="req">*</span></label>
                <input type="text" value={draft.position} onChange={e => set('position', e.target.value)} placeholder='e.g. "Concourse Â· Above escalator E2"' />
              </div>
