                  {+draft.closestSchoolM > 0 && +draft.closestSchoolM < 400 ? 'âš  Under 400 m â€” category restrictions will apply.' : 'For category-restricted content filtering.'}
                </span>
              </div>
            </div>
          </div>
        )}

        {step === 3 && (
          <div className="surface">
            <div className="section-block">
              <h2>Format Â· tech specs</h2>
              <div className="lead">Pick values from master data. Need a new option? Open Master data â†’ Formats.</div>
              <div style={{display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 16}}>
                <div className="field"><label>Technology <span className="req">*</span></label><select value={draft.tech} onChange={e => set('tech', e.target.value)}>{TECHS.map(t => <option key={t}>{t}</option>)}</select></div>
                <div className="field"><label>Orientation</label><select value={draft.orientation} onChange={e => set('orientation', e.target.value)}><option>Landscape</option><option>Portrait</option></select></div>
                <div className="field"><label>Illumination</label><select value={draft.illumination} onChange={e => set('illumination', e.target.value)}><option>Internal LED</option><option>Backlit</option><option>Front-lit</option><option>None</option></select></div>
                <div className="field"><label>Dimensions (W Ã— H mm)</label><input type="text" value={draft.dimensions} onChange={e => set('dimensions', e.target.value)} placeholder="1920 Ã— 1080 mm" /></div>
                <div className="field"><label>Resolution (px)</label><input type="text" value={draft.resolution} onChange={e => set('resolution', e.target.value)} placeholder="1920 Ã— 1080 px" /></div>
                <div className="field"><label>Slot length / share</label><input type="text" value={draft.slot} onChange={e => set('slot', e.target.value)} placeholder="10s Â· 6/min" /></div>
              </div>
            </div>
          </div>
        )}

        {step === 4 && (
          <div className="surface">
            <div className="section-block">
              <h2>Link external IDs (optional)</h2>
              <div className="lead">Add identifiers used by downstream systems to reference this frame. You can also link these later.</div>
              <ExternalIdsTable ids={draft.externalIds} editable />
              <div className="banner" style={{marginTop: 16}}>
                <Icon.info /> External ID systems are master data â€” add a new system via Master data â†’ External ID Systems.
              </div>
            </div>
          </div>
        )}

        {step === 5 && (
          <div className="surface" style={{padding: 24}}>
            <h2 style={{fontSize: 16, fontWeight: 600, marginBottom: 14}}>Review & create</h2>
            <KVGrid entries={[
              ['Description', draft.description || 'â€”', { muted: !draft.description }],
              ['Region Â· Town', `${draft.region} Â· ${draft.town || 'â€”'}`],
              ['Postcode', draft.postcode || 'â€”', { mono: true, muted: !draft.postcode }],
              ['Site', `${draft.siteType} Â· ${draft.siteName || 'â€”'}`],
              ['Position', draft.position || 'â€”'],
              ['Closest school', draft.closestSchoolM ? `${draft.closestSchoolM} m` : 'â€”', { muted: !draft.closestSchoolM }],
              ['Tech', draft.tech],
              ['Dimensions', draft.dimensions || 'â€”', { mono: true, muted: !draft.dimensions }],
              ['Resolution', draft.resolution || 'â€”', { mono: true, muted: !draft.resolution }],
              ['Illumination', draft.illumination],
              ['Slot', draft.slot],
              ['Status', <StatusChip status={draft.status} />],
              ['External IDs', draft.externalIds.length ? `${draft.externalIds.length} linked` : 'None yet', { muted: !draft.externalIds.length }],
            ]} />
            <div className="banner" style={{marginTop: 18}}>
              <Icon.info /> A new internal ID will be assigned on create (next: <span className="mono">FRM-01210</span>).
            </div>
          </div>
        )}

        <div className="sticky-bar" style={{marginTop: 0}}>
          <span className="left">Step {step} of {steps.length} Â· {steps[step-1].label}</span>
          <span className="spacer" />
          <button className="btn ghost" onClick={onCancel}>Cancel</button>
          {step > 1 && <button className="btn outlined" onClick={prev}><Icon.chevL /> Back</button>}
          {step < 5
            ? <button className="btn primary" onClick={next}>Continue <Icon.chev /></button>
            : <button className="btn primary" onClick={() => onCreate(draft)}><Icon.check /> Create frame</button>
          }
        </div>
      </div>
    </React.Fragment>
  );
}

/* -------------------------------------------------------------------------- */
/* Master data: shared shell + 4 sections                                     */
/* -------------------------------------------------------------------------- */
const MD_CONTENT = {
