    ],
    rows: () => {
      const { FRAMES } = window.FRAME_DATA;
      const systems = [
        { name: 'Route OCS',     desc: 'UK out-of-home audience measurement body â€” official frame registry.', patt: 'RTE-OOH-#####', owner: 'Tom Reuter' },
        { name: 'Broadsign CMS', desc: 'Digital signage playback CMS â€” used for ad scheduling on digital frames.', patt: 'BS-AAA-#####', owner: 'Maya Patel' },
        { name: 'AdSquare DSP',  desc: 'Programmatic demand-side platform â€” inventory exposed for bidding.', patt: 'AS-####', owner: 'Maya Patel' },
