            </div>
            <div style={{flex: 1}} />
            <span className="chip">{g.values.length} values</span>
            <button className="btn outlined sm" onClick={() => onAdd && onAdd(g)}><Icon.plus width="13" height="13" /> Add value</button>
          </div>
          <table className="tbl">
            <thead>
