      <div className="group">Master data</div>
      {md.map(it => (
        <a key={it.id} href="#" onClick={e => handle(e, it.id)} className={"nav" + (active === it.id ? ' active' : '')}>
          <it.icon /> {it.label}
        </a>
      ))}
      <div className="spacer" />
      <div className="footer">
        Frame Inventory v0.4.2<br/>
        Last sync Â· 2 min ago
