+.button-link { min-height: auto; padding: 2px; color: var(--primary-main); background: transparent; border: 0; font-size: 12px; }
+.button-link:hover:not(:disabled) { color: var(--primary-dark); background: transparent; text-decoration: underline; }
+.button:disabled { color: var(--text-disabled); background: var(--gray-50); cursor: not-allowed; }
+
+.results { min-width: 0; padding: var(--space-5) var(--space-6) var(--space-8); }
+.surface { overflow: hidden; background: var(--white); border: 1px solid var(--border-subtle); border-radius: var(--radius-lg); }
+.table-scroll { overflow-x: auto; }
