+.status-chip::before { width: 6px; height: 6px; background: currentColor; border-radius: 50%; content: ''; opacity: .7; }
+.status-live { color: var(--green-1200); background: var(--green-100); }
+.status-inactive { color: var(--gray-1000); background: var(--gray-100); }
