+.state-panel h2 { margin: 0; font-size: 16px; font-weight: 600; }
+.state-panel p { margin: 6px 0 var(--space-4); color: var(--text-secondary); font-size: 13px; }
+.loading-spinner { width: 20px; height: 20px; border: 2px solid var(--blue-200); border-top-color: var(--primary-main); border-radius: 50%; animation: spin 700ms linear infinite; }
+@keyframes spin { to { transform: rotate(360deg); } }
+@media (prefers-reduced-motion: reduce) { .loading-spinner { animation: none; } }
+
+.pagination { gap: var(--space-3); min-height: 52px; padding: 9px 14px; color: var(--text-secondary); background: var(--gray-50); border-top: 1px solid var(--border-subtle); font-size: 12px; }
+.pagination-spacer { flex: 1; }
+.page-size { gap: 8px; white-space: nowrap; }
+.page-size .select { width: 68px; height: 30px; }
+.page-controls { gap: 6px; }
+.page-indicator { min-width: 88px; text-align: center; }
+
+@media (max-width: 960px) {
+  .inventory-layout { grid-template-columns: 1fr; }
+  .filters { border-right: 0; border-bottom: 1px solid var(--border-subtle); }
+  .filter-list { display: grid; grid-template-columns: repeat(3, minmax(150px, 1fr)); }
+}
+
+@media (max-width: 720px) {
+  .app-shell { grid-template: 56px 40px minmax(0, 1fr) / 1fr; grid-template-areas: 'brand' 'topbar' 'content'; }
